function slug(s) {
  return String(s)
    .toLowerCase()
    .trim()
    .replace(/[\s\/]+/g, "-")
    .replace(/[^a-z0-9\-_]+/g, "")
    .slice(0, 80);
}

const { kb_ref, doc, section, source_url, tags, doc_id, text } = $json;

const TARGET = 850;
const OVERLAP = 120;

const hard = String(text).replace(/\r\n/g, "\n").trim();
const parts = hard.split(/\n{2,}/g).map(s => s.trim()).filter(Boolean);

let chunks = [];
let buf = "";

function pushBuf() {
  const t = buf.trim();
  if (t) chunks.push(t);
}

for (const p of parts) {
  if ((buf + "\n\n" + p).length <= TARGET) {
    buf = buf ? (buf + "\n\n" + p) : p;
  } else {
    pushBuf();
    const tail = buf.slice(Math.max(0, buf.length - OVERLAP));
    buf = (tail ? tail + "\n\n" : "") + p;
  }
}
pushBuf();

const now = new Date().toISOString();

return chunks.map((chunk_text, i) => {
  const chunk_id = `${kb_ref}__${slug(doc)}__${slug(section)}__${i}`;

  return {
    json: {
      chunk_id,
      kb_ref,
      doc,
      section,
      source_url: source_url || null,
      doc_id: doc_id || null,
      chunk_text,
      chunk_index: i,
      tags: Array.isArray(tags) ? tags : null,
      updated_at: now
    }
  };
});

const tags_json = Array.isArray($json.tags) ? JSON.stringify($json.tags) : null;

return [{
  json: {
    ...$json,
    embedding_input: $json.chunk_text,
    tags_json
  }
}];

const chunk = $items("KB — Snapshot Chunk")[0].json;
const emb = $json?.data?.[0]?.embedding;

if (!Array.isArray(emb)) {
  throw new Error("No embedding found at data[0].embedding");
}

const embedding_vector = `[${emb.join(",")}]`;
return [{
  json: {
    ...chunk,
    embedding: embedding_vector
  }
}];

