// KB — Ingest v1 (Webhook) :: Validate Input (Code node)
// No require('url') — disallowed in n8n Cloud sandbox.
// Canonicalize only X/Twitter status URLs using regex.

const b = $json?.body ?? $json;

// --- Auth (webhook secret) ---
const secret = $vars.INGEST_WEBHOOK_SECRET;
const got =
  $json?.headers?.["x-webhook-secret"] ??
  $json?.headers?.["X-Webhook-Secret"] ??
  $json?.request?.headers?.["x-webhook-secret"] ??
  $json?.request?.headers?.["X-Webhook-Secret"];

if (!secret) throw new Error("INGEST_WEBHOOK_SECRET missing in n8n Variables");

if (got !== secret) {
  return [{ json: { ok: false, status: "UNAUTHORIZED" } }];
}

// --- Helpers ---
function cleanStr(v) {
  return (v ?? "").toString().trim();
}

// Returns canonical x.com status URL OR null
function canonicalizeXStatusUrl(input) {
  const s = cleanStr(input);
  if (!s) return null;

  // accept: https://x.com/<handle>/status/<id>...
  //         https://twitter.com/<handle>/status/<id>...
  //         with www./mobile. prefixes, and optional tail/query/hash
  const re = /^https?:\/\/(?:(?:www|mobile)\.)?(x\.com|twitter\.com)\/([A-Za-z0-9_]{1,15})\/status\/(\d+)(?:[/?#].*)?$/i;
  const m = s.match(re);
  if (!m) return null;

  const handle = m[2];
  const tweetId = m[3];
  return `https://x.com/${handle}/status/${tweetId}`;
}

// detect if URL looks like it belongs to x/twitter at all
function isXorTwitterUrl(input) {
  const s = cleanStr(input);
  if (!s) return false;
  return /^https?:\/\/(?:(?:www|mobile)\.)?(x\.com|twitter\.com)\//i.test(s);
}

// --- Required fields ---
const kb_ref = cleanStr(b.kb_ref);
const doc = cleanStr(b.doc);
const section = cleanStr(b.section);
const text = cleanStr(b.text);

const missing = [];
if (!kb_ref) missing.push("kb_ref");
if (!doc) missing.push("doc");
if (!section) missing.push("section");
if (!text) missing.push("text");

if (missing.length) {
  return [{
    json: {
      ok: false,
      error: { code: "missing_required_fields", missing }
    }
  }];
}

// --- source_url normalize (Variant A) ---
let source_url_raw = cleanStr(b.source_url);
let source_url = null;

if (source_url_raw) {
  const canon = canonicalizeXStatusUrl(source_url_raw);

  if (canon) {
    source_url = canon;
  } else if (isXorTwitterUrl(source_url_raw)) {
    // strict: x/twitter but not a status link → drop
    source_url = null;
  } else {
    // non-x URLs: keep as-is (no parsing in sandbox)
    source_url = source_url_raw;
  }
}

// --- Output (normalized payload for downstream ingest) ---
return [{
  json: {
    ok: true,
    kb_ref,
    doc,
    section,
    source_url, // canonical or null
    tags: Array.isArray(b.tags) ? b.tags : null,
    doc_id: b.doc_id || null,
    replace: !!b.replace,
    text
  }
}];

// Берём исходный нормализованный item из ноды Validate Input
const original = $items("Validate Input")[0].json;
return [{ json: original }];

const original = $items("Validate Input")[0].json;
const chunksCount = $items("KB — Chunk Docs v1").length;
const lastChunk = $items("KB — Chunk Docs v1")[chunksCount - 1]?.json;

return [{
  json: {
    ok: true,
    kb_ref: original.kb_ref,
    doc: original.doc,
    section: original.section,
    doc_id: original.doc_id,
    replace: original.replace,
    chunks_upserted: chunksCount,
    last_chunk_id: lastChunk?.chunk_id ?? null
  }
}];
